// Expect { sessionId, exercise: 'squat'|'pushup'|'plank', targetReps?, targetSeconds? }
const { sessionId, exercise, targetReps, targetSeconds } = $json;
return [{ json: { sessionId, exercise, targetReps, targetSeconds, startedAt: Date.now() } }];

// Expect { sessionId, exercise, keypoints: [...], fps? }
// Simple rep counting for squat/pushup via hip or elbow angle thresholds
const data = $json;
const prev = $json.prev || {};
function angle(a,b,c){
  const ab = { x: a.x-b.x, y: a.y-b.y };
  const cb = { x: c.x-b.x, y: c.y-b.y };
  const dot = ab.x*cb.x + ab.y*cb.y;
  const mag = Math.sqrt(ab.x*ab.x+ab.y*ab.y)*Math.sqrt(cb.x*cb.x+cb.y*cb.y);
  const cos = Math.max(-1, Math.min(1, dot/(mag||1)));
  return Math.acos(cos) * 180/Math.PI;
}
// Map names to points
const points = {};
(data.keypoints||[]).forEach(p=> points[p.name]=p);
let reps = prev.reps || 0;
let phase = prev.phase || 'up';
if (data.exercise === 'squat') {
  const knee = points['right_knee'] || points['left_knee'];
  const hip = points['right_hip'] || points['left_hip'];
  const ankle = points['right_ankle'] || points['left_ankle'];
  if (knee && hip && ankle) {
    const kneeAngle = angle(hip, knee, ankle);
    if (phase === 'up' && kneeAngle < 90) { phase = 'down'; }
    if (phase === 'down' && kneeAngle > 160) { phase = 'up'; reps += 1; }
  }
}
if (data.exercise === 'pushup') {
  const shoulder = points['right_shoulder'] || points['left_shoulder'];
  const elbow = points['right_elbow'] || points['left_elbow'];
  const wrist = points['right_wrist'] || points['left_wrist'];
  if (shoulder && elbow && wrist) {
    const elbowAngle = angle(shoulder, elbow, wrist);
    if (phase === 'up' && elbowAngle < 70) { phase = 'down'; }
    if (phase === 'down' && elbowAngle > 160) { phase = 'up'; reps += 1; }
  }
}
return [{ json: { sessionId: data.sessionId, exercise: data.exercise, reps, phase } }];

